const test=require('node:test'),assert=require('node:assert/strict');
test('all exact cell edges and vertices stay inside the hex union',async()=>{const {containsBoardPoint}=await import('../board-bounds.js'),{BOARD_CELLS}=await import('../board-terrain.js'),{cellWorld}=await import('../playground-model.js');for(const cell of BOARD_CELLS){const c=cellWorld(cell);for(let edge=0;edge<6;edge++){const a=edge*Math.PI/3,b=(edge+1)*Math.PI/3;for(let step=0;step<=10;step++){const t=step/10,x=c.x+50*((1-t)*Math.sin(a)+t*Math.sin(b)),z=c.z+50*((1-t)*Math.cos(a)+t*Math.cos(b));assert(containsBoardPoint(x,z),JSON.stringify({cell,edge,t,x,z}));}}}});
test('diagnosed seam points pass but real exterior points and nonfinite coordinates do not',async()=>{const {containsBoardPoint,createHexBounds}=await import('../board-bounds.js');for(const [x,z]of [[-346.41016151377545,-228.75],[-346.41016151377545,-371.85],[-238.15698604072062,262.5],[-238.15698604072062,187.5]])assert(containsBoardPoint(x,z));const contains=createHexBounds([{q:0,r:0}]);assert(!contains(Math.sqrt(3)*25+.001,0));assert(!contains(0,50.001));assert(!contains(NaN,0));assert(!contains(0,Infinity));});
